def leaderboard(names, scores):
    rows = []
    for i in range(len(names)):
        rows.append(str(i + 1) + ". " + names[i] + ": " + str(scores[i]))
    return rows

def merge_sorted(a, b):
    out = []
    while a and b:
        if a[0] <= b[0]:
            out.append(a.pop(0))
        else:
            out.append(b.pop(0))
    while a:
        out.append(a.pop(0))
    while b:
        out.append(b.pop(0))
    return out
